(7264, 588, 53, '<table>\r\n<tbody>\r\n<tr>\r\n<td><strong>- president</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- rain</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- concentric</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- compass</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- zen square</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- elegance</strong></td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>president</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- het basis hotel servies voor elke horeca onderneming</td>\r\n</tr>\r\n<tr>\r\n<td>- ronde borden</td>\r\n</tr>\r\n<tr>\r\n<td>- soepkoppen &amp; schotels</td>\r\n</tr>\r\n<tr>\r\n<td>- kommen</td>\r\n</tr>\r\n<tr>\r\n<td>- zout &amp; peper stellen</td>\r\n</tr>\r\n<tr>\r\n<td>- sauci&egrave;res</td>\r\n</tr>\r\n<tr>\r\n<td>- koffie- en theeserviezen</td>\r\n</tr>\r\n<tr>\r\n<td>- mokken</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>rain</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- licht horeca porselein met design reli&euml;f</td>\r\n</tr>\r\n<tr>\r\n<td>- borden</td>\r\n</tr>\r\n<tr>\r\n<td>- soepkoppen &amp; schotels</td>\r\n</tr>\r\n<tr>\r\n<td>- kommen</td>\r\n</tr>\r\n<tr>\r\n<td>- koffie- en theeserviezen</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>concentric</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- een oersterk horeca servies met garantie</td>\r\n</tr>\r\n<tr>\r\n<td>- speciaal ontwikkeld voor intensief gebruik</td>\r\n</tr>\r\n<tr>\r\n<td>- rekening gehouden met stapelbaarheid</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>compass</strong></td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>etc.</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>'),
