(20095, 3892, 53, '<table>\r\n<tbody>\r\n<tr>\r\n<td><strong>- woningmakelaardij</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- bedrijfsmakelaardij</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- horecamakelaardij</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- aankoopbegeleiding</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- taxatie\\''s</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- adviezen</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(20096, 3892, 56, '<table>\r\n<tbody>\r\n<tr>\r\n<td><strong>- familiebedrijf</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- service, vakbekwaamheid, discretie en kennis van de regio</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- in staat zeer efficient te werken</strong></td>\r\n</tr>\r\n</tbody>\r\n</table>'),
(20097, 3892, 48, '<p><strong>scherpe prijs</strong></p>'),
(20098, 3892, 126, '<p><strong>- van tevoren duidelijke afspraken </strong></p>\r\n<p><strong>- persoonlijk gesprek</strong></p>'),
