(20100, 4111, 53, '<table>\r\n<tbody>\r\n<tr>\r\n<td><strong>- transacties</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- advies</strong></td>\r\n</tr>\r\n<tr>\r\n<td><strong>- investment</strong></td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>waardering</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- beoordeling van de huidige exploitatie en de potentie</td>\r\n</tr>\r\n<tr>\r\n<td>- mede gebaseerd op marktstudie van vraag en aanbod</td>\r\n</tr>\r\n<tr>\r\n<td>- concurrentieanalyse</td>\r\n</tr>\r\n<tr>\r\n<td>- uitbreidingsmogelijkheden</td>\r\n</tr>\r\n<tr>\r\n<td>- eventueel een alternatieve aanwendbaarheid</td>\r\n</tr>\r\n<tr>\r\n<td>- met internationaal erkende waarderingsmodellen</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>informatie memorandum</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- een representatief Informatie Memorandum</td>\r\n</tr>\r\n<tr>\r\n<td>- voor een klein aantal geselecteerde gegadigden</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>benadering</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- op discrete wijze</td>\r\n</tr>\r\n<tr>\r\n<td>- goede internationale contacten bij investeerders en hoteloperators</td>\r\n</tr>\r\n<tr>\r\n<td>- staat ge&iuml;nterresseerden te woord en arrangeert hotelbezichtigingen</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>onderhandeling</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- de best mogelijke prijs tegen de best mogelijke condities</td>\r\n</tr>\r\n<tr>\r\n<td>- het sluiten van de overeenkomst</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>due diligence en overdracht</strong></td>\r\n</tr>\r\n<tr>\r\n<td>- verstrekken informatie, co&ouml;rdineren afspraken en informeren van&nbsp;de opdrachtgever</td>\r\n</tr>\r\n<tr>\r\n<td>- co&ouml;rdineren de overdracht samen met de jurist, accountant en technisch adviseur</td>\r\n</tr>\r\n<tr>\r\n<td>&nbsp;</td>\r\n</tr>\r\n<tr>\r\n<td><strong>advies</strong><