(21161, 132, 56, '<p><strong>* een wasserij van betekenis</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* kwaliteit leveren, aandacht voor wensen, betrouwbaar en integer</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* maatschappelijk verantwoord ondernemen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* aandacht voor het milieu</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* goede werkgever voor de medewerkers</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* zakelijke markt: horeca, bedrijven en zorginstellingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* particuliere markt</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* zorg voor de grote en de kleine ''wasjes''</strong></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(21162, 132, 53, '<p><strong>Binnenkomst was- en linnengoed</strong></p>\r\n<p>&nbsp;</p>\r\n<p>- wegen en telling</p>\r\n<p>- ingangscontrole en sorteren</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Wasproces</strong></p>\r\n<p>&nbsp;</p>\r\n<p>- wassen en drogen</p>\r\n<p>- controle</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Strijkproces</strong></p>\r\n<p>&nbsp;</p>\r\n<p>- mangelen en strijken</p>\r\n<p>- controle</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Nabewerking</strong></p>\r\n<p>&nbsp;</p>\r\n<p>- vouwen en verpakken</p>\r\n<p>- eindcontrole</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Aflevering</strong></p>\r\n<p>&nbsp;</p>\r\n<p>- op de afgesproken dag en tijd</p>\r\n<p>- met eigen bezorgdienst</p>'),
(21163, 7445, 56, '<p><strong>* een ambitieus bedrijf</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met een oud verleden en een jonge visie</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met de nodige kennis en ervaring</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* enorm professioneel en modern</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* toegelegd op het gespecialiseerde werk</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* een persoonlijke benadering</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* diverse klantenkring</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* de service staat als een huis</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* duurzame oplossingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* voldoen aan de strengste milieu-eisen</strong></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(21164, 7445, 53, '<p><strong>Horeca</strong></p>\r\n<p>- veel hotels en restaurants</p>\r\n<p>- groot of klein</p>\r\n<p>- ook voor huur, in samenwerking met gerenommeerde fabrikanten</p>\r\n<p>- tafellakens, lopers, servetten, theedoeken, kokskleding, tafelrokken etc.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Verpleeg- en bejaardenhuizen</strong></p>\r\n<p>- voor veel instellingen in de regio</p>\r\n<p>- linnenpakket kan eigendom zijn van de instelling</p>\r\n<p>- huur is ook mogelijk (bedlinnen, badlinnen en doeken)</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Bedrijfskleding</strong></p>\r\n<p>- naar wens hangend of gevouwen geleverd</p>\r\n<p>- op naam van de drager of op maat</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Extra service</strong></p>\r\n<p>- rolhanddoekautomaten</p>\r\n<p>- rolhanddoeken</p>\r\n<p>- schoonloopmatten</p>\r\n<p>- ophalen en weer bezorgen door onze chauffeur</p>'),
