(21314, 1624, 56, '<p><strong>* leverancier van muziek- en bedieningsvriendelijke computers</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* marktleider</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* in nauwe samenwerking met de horeca ontwikkeld</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* oneindig veel muzieknummers</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* altijd de nieuwste releases</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* handzaam ingedeeld</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* mogelijkheid voor beeld, advertising, karaoke, videoclips etc.</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* ideaal bedieningsgemak</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* gratis demo</strong></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
