(21806, 8415, 56, '<p><strong>* specialist in professionele koffieautomaten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* breed scala aan gerenommeerde koffiemerken (ook fairtrade)</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* de focus ligt op gebruiksgemak</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met technisch vernunft en slimme logistiek</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* het allerbeste product tegen de beste prijs</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* uitgebreid servicenetwerk</strong></p>'),
(21807, 8415, 53, '<p><strong>Koffieautomaten</strong></p>\r\n<p>- instant machines</p>\r\n<p>- espresso machines</p>\r\n<p>- freshbrew machines</p>\r\n<p>- snelfilter machines</p>\r\n<p>- koudwater machines</p>\r\n<p>- overige machines</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Ingredi&euml;nten</strong></p>\r\n<p>- koffie</p>\r\n<p>- suiker en melk</p>\r\n<p>- cappuccino</p>\r\n<p>- chocolade</p>\r\n<p>- thee</p>\r\n<p>- soep</p>\r\n<p>- bij de koffie</p>\r\n<p>- frisdranken</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Disposables</strong></p>\r\n<p>- bekers</p>\r\n<p>- roerstaafjes</p>\r\n<p>- papierrollen</p>\r\n<p>- filterpapier</p>\r\n<p>- draagtrays</p>\r\n<p>- bekerhouder</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Toebehoren</strong></p>\r\n<p>- kop en schotel</p>\r\n<p>- waterglaasjes</p>\r\n<p>- bekers</p>\r\n<p>- kannen</p>\r\n<p>- warmhoudkast</p>\r\n<p>- refill</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Onderhoud</strong></p>\r\n<p>- waterfilters</p>\r\n<p>- reiniger</p>'),
(21808, 8415, 76, '<p><strong>* levering binnen 48 uur, maar meestal sneller</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* bij storing binnen 8 uur ter plekke</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* vervangende automaten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* Full Service Plus</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* automatenwijzer: welke automaat past het beste bij uw bedrijf</strong></p>'),
(21809, 8415, 1, '<p><strong>* westrom risse facilitair</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* holbox</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* salon capelli</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* rivierdael notarissen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* boerenbond</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* L1</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* neptunus</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* basisscholen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* flower power</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* weir minerals</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* etc.</strong></p>'),
