(21813, 8410, 48, '<p><strong>prijslijsten op de website</strong></p>'),
(21814, 8410, 86, '<p><strong>winkelwagen</strong></p>'),
(21815, 8407, 56, '<p><strong>* een jong en dynamisch bedrijf</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* kwaliteit staat bij Cafe-K voorop</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* &uacute;w partner met een compleet koffieconcept voor MKB en Horeca</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* dealer van uitsluitend gereonmmeerde merken (Franke, WMF, Sielaff en Jura)</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* exclusieve melanges van de hoogste kwaliteit</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* one-stop shopping</strong></p>'),
