(21918, 5874, 53, '<p><strong>- olieverlengend, fotokatalystisch en keramisch apparaat</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- kan in alle friteuses gebruikt worden</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- frituurolie hoeft minder vaak ververst te worden</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- lagere kosten en meer rendement</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- veilig, niet chemisch en maakt geen gebruik van bewegende deeltjes</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- gepantenteerd in Japan en geautoriseerd in verschillende landen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- onderhouds- en gebruiksvriendelijk</strong></p>'),
(21919, 2579, 56, '<p><strong>- bestaat 70 jaar</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- hoog aantal kiloWatts afbakvermogen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- in combinatie met een economisch ''kleine'' vet- of olie-inhoud</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- door de jaren heen steeds moderner, krachtiger en zuiniger geworden</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- &eacute;&eacute;n van de oudste frituurovenfabrikanten van Europa</strong></p>'),
(21920, 2579, 53, '<p><strong>Retro - Nieuw!</strong></p>\r\n<p>- authentieke kracht met hedendaags design</p>\r\n<p>- verbonden aan het 7-jarig jubileum</p>\r\n<p>- een combinatie van de opgebouwde kennis en een hedendaags design</p>\r\n<p>- zeer opvallende vormgeving</p>\r\n<p>- bakken met de gemakken van nu met de uitstraling van toen</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Summum</strong></p>\r\n<p>- 50 jaar perfectie</p>\r\n<p>- leverbaar in elke vermogensklasse</p>\r\n<p>- het tekstdisplay is tot 5 meter goed leesbaar</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Concorde</strong></p>\r\n<p>- zoals u hem wilt</p>\r\n<p>- uitermate geschikt voor&nbsp; de fastfood-zaak die met vierkante ketels en manden wil werken</p>\r\n<p>- ook uit te rusten met ronde of rechthoekige ketels</p>\r\n<p>- uitermate gebruiksvriendelijk</p>\r\n<p>- eenvoudig schoon te maken</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Perfectime</strong></p>\r\n<p>- altijd de perfecte timing</p>\r\n<p>- een echte winnaar</p>\r\n<p>- gestroomlijnde golvende vormen</p>\r\n<p>- won de Nederlandse Innovatieprijs</p>\r\n<p>- is oerdegelijk</p>\r\n<p>- veelal voor de zwaardere vermogensklasse</p>\r\n<p>- gewoon indrukwekkend</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Vis-Eco</strong></p>\r\n<p>- is ontwikkeld samen met 12 visondernemers</p>\r\n<p>- zij wilde grotere ketels, gemakkelijk schoon te maken en met weinig energieverbruik</p>\r\n<p>- 44% energie investeringsaftrek (EIA)</p>\r\n<p>- naadloos toestel</p>\r\n<p>- wordt sinds enkele jaren verkocht door Smitto-Vis-Eco</p>'),
