(22468, 7415, 119, '<p><strong>zie website</strong></p>'),
(22469, 7415, 53, '<p><strong>- algemeen</strong></p>\r\n<p><strong>- bedlinnen</strong></p>\r\n<p><strong>- badlinnen</strong></p>\r\n<p><strong>- tafellinnen</strong></p>\r\n<p><strong>- kleding en overige producten</strong></p>\r\n<p><strong>- informatiesystemen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>algemeen</strong></p>\r\n<p>- een hoogwaardig eigen linnenpakket</p>\r\n<p>- van topleveranciers</p>\r\n<p>- keuze voor design en kleur is vrij</p>\r\n<p>&nbsp;</p>\r\n<p><strong>bedlinnen</strong></p>\r\n<p>- adviezen bij de juiste keuze</p>\r\n<p>- hoeveelheid linnen is uniek in de verhuurmarkt</p>\r\n<p>- 5-voudige insteek van het bedlinnen</p>\r\n<p>- meer aandacht voor GOTS en Fairtrade</p>\r\n<p>&nbsp;</p>\r\n<p><strong>badlinnen</strong></p>\r\n<p>- van bont en ingeweven badgoed tot uni-wit</p>\r\n<p>- 7-voudige insteek</p>\r\n<p>&nbsp;</p>\r\n<p><strong>tafellinnen</strong></p>\r\n<p>- breed scala van mogelijkheden</p>\r\n<p>- kleuren en maten</p>\r\n<p>&nbsp;</p>\r\n<p><strong>kleding en overige producten</strong></p>\r\n<p>- diverse modellen kleding (koks, keukenpersoneel, kamermeisjes)</p>\r\n<p>- met een kledingbeheersysteem</p>\r\n<p>- complementaire producten (kussens, dekbedden, dekens, tafelrokken, sloven en theedoeken)</p>\r\n<p>&nbsp;</p>\r\n<p><strong>informatiesystemen</strong></p>\r\n<p>- via het unieke intranet van Nedlin</p>\r\n<p>- uitgebreid palet van managementinformatie</p>\r\n<p>- inzicht in verbruikcijfers en kosten</p>\r\n<p>- toegang tot reclameformulieren en het linnenhandboek</p>'),
(22470, 7415, 16, '<p><strong>- op het juiste moment over de juiste hoeveelheid linnen beschikken</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- alle logistieke werkzaamheden in eigen beheer</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- zeer flexibel reageren op wisselende vraag</strong></p>'),
