(23111, 7121, 1, '<p><strong>Horeca</strong></p>\r\n<p>- unlimited label</p>\r\n<p>- Pain uotidien</p>\r\n<p>- Meyer beheer</p>\r\n<p>- Debuut horecabeheer en ontwikkeling</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Wellness</strong></p>\r\n<p>- Delete</p>\r\n<p>- Thermen &amp; Beautygroup</p>\r\n<p>- Centre du Lac</p>\r\n<p>- Elysium</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Hotels</strong></p>\r\n<p>- Swiss&ocirc;tel</p>\r\n<p>- Scandic</p>\r\n<p>- Mercure</p>\r\n<p>- Pullman</p>\r\n<p>- Novotel</p>\r\n<p>- WestCord</p>\r\n<p>- Bilderberg</p>\r\n<p>- Accor</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Musea</strong></p>\r\n<p>- Joods Historisch Museum</p>\r\n<p>- Amsterdam Museum</p>\r\n<p>- House of Bols</p>\r\n<p>- Stedelijk Museum</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Brands &amp; FMCG</strong></p>\r\n<p>- Coca-Cola</p>\r\n<p>- Vrumona</p>\r\n<p>- Lipton Ice Tea</p>\r\n<p>- Unilever</p>\r\n<p>- Douwe Egberts</p>\r\n<p>- Aquarius</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Entertainment &amp; Leisure</strong></p>\r\n<p>- Booking.com</p>\r\n<p>- Bison Bowling</p>\r\n<p>- Super Fun</p>\r\n<p>- MartiniPlaza</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Retail</strong></p>\r\n<p>- Gerzon</p>\r\n<p>- Wlleroy &amp; Boch</p>\r\n<p>- Guess</p>\r\n<p>- lief! lifestyle</p>'),
(23112, 9605, 0, ''),
(23113, 7121, 53, '<p><strong>- mystery visit</strong></p>\r\n<p><strong>- mystery shopping</strong></p>\r\n<p><strong>- promotional checks</strong></p>\r\n<p><strong>- training</strong></p>\r\n<p><strong>- guest surveys</strong></p>\r\n<p><strong>- communication tools</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Mystery Visit</strong></p>\r\n<p>- qb loopt een dagdeel mee in de organisatie</p>\r\n<p>- samenstellen van vragenlijst en toetsingscriteria met o.a. medewerker input</p>\r\n<p>- communicatie naar de organisatie en haar medewerkers</p>\r\n<p>- eerste toetsing van de Mystery Visitor</p>\r\n<p>- tussentijdse- of eindevaluatie om bevindingen en ervaringen te bespreken</p>\r\n<p>- training met input van de Mystery Visit</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(23114, 7123, 53, '<p><strong>- er wordt onderscheid gemaakt in algemene en specifieke onderzoeksaspecten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- er is een standaard checklist voor algemene onderzoeksaspecten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- bijv. wachttijden, klantvriendelijkheid, communicatieve vaardigheden en uiterlijke verzorging</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- alle mystery guests rapporteren over de algemene onderzoeksaspecten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- vervolgens onderverdeling naar specifieke onderzoeksopdrachten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- 2&nbsp;&agrave; 3 mystery guests rapporteren vervolgens over de specifieke onderzoekopdrachten</strong></p>\r\n<p><strong>&nbsp;</strong></p>'),
(23115, 7123, 48, '<p><strong>Pakket A - 335 euro</strong></p>\r\n<p>- 5&nbsp; bezoeken door verschillende mystery guests</p>\r\n<p>- tijdspanne 2 tot 3 maanden</p>\r\n<p>- observatie van 19 onderdelen en elk 5 detailpunten</p>\r\n<p>- observatie begint bij het telefonisch reserveren</p>\r\n<p>- observatie eindigt na het verlaten van de zaak</p>\r\n<p>- document voor het inlichten van het personeel</p>\r\n<p>- rapport per gehouden bezoek</p>\r\n<p>- eindrapportage van het totale onderzoek</p>\r\n<p>- aanbeveling op basis van het gehouden onderzoek</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Pakket&nbsp;B - 425 euro</strong></p>\r\n<p>- 5&nbsp; bezoeken door verschillende mystery guests</p>\r\n<p>- tijdspanne 2 tot 3 maanden</p>\r\n<p>- observatie van 19 onderdelen en elk 5 detailpunten</p>\r\n<p><strong>- 12 zelf te benoemen details voor onderzoek (geen personen)</strong></p>\r\n<p>- observatie begint bij het telefonisch reserveren</p>\r\n<p>- observatie eindigt na het verlaten van de zaak</p>\r\n<p>- document voor het inlichten van het personeel</p>\r\n<p>- rapport per gehouden bezoek</p>\r\n<p>- eindrapportage van het totale onderzoek</p>\r\n<p>- aanbeveling op basis van het gehouden onderzoek</p>\r\n<p>&nbsp;</p>'),
(23116, 3798, 56, '<p><strong>* POS kassasystemen voor horeca automatisering</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* bestaat uit een 4-tal innovatieve software oplossingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* voor iedereen toegankelijk, zowel qua gebruikers vriendelijkheid als financieel</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* Dutch Solutions is een compacte en klantgerichte organisatie</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* ondersteuning wordt direct online aangeboden</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* ook voor rechstreeks leveren en installeren vande horeca kassa software</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* dit levert u een aanzienlijk kostenvoordeel op</strong></p>'),
(23117, 3798, 3, '<p><strong>Horeca</strong></p>'),
(23118, 3798, 53, '<p><strong>- POS kassa software</strong></p>\r\n<p><strong>- Online bestel software</strong></p>\r\n<p><strong>- iPOS: mobiel kassasysteem</strong></p>\r\n<p><strong>- Mobiel bestellen voor de consument op basis van QR code</strong></p>\r\n<p>&nbsp;</p>\r\n<p>- software oplossingen voor alle bestel- en afrekenhandelingen binnen de horeca</p>\r\n<p>- centraal staan de gasten-, tafel- en contantbon</p>\r\n<p>- bestellingen kunnen uitermate snel en effici&euml;nt worden ingevoerd</p>\r\n<p>- u kunt direct in de bon werken, uniek voor de Nederlandse horeca-branche</p>\r\n<p>- aantal bedieningsknoppen en handelingen zijn tot een minimum beperkt</p>\r\n<p>- de touchscreen kassa is voor iedere horeca-medewerker binnen 5 minuten glashelder</p>\r\n<p>- via ''klantinstellingen'' kunnen de wensen van de horeca ondernemer worden ingericht</p>\r\n<p>- met een zeer uitgebreide keukenversie, incl. printen van bestellingen op meerdere locaties</p>\r\n<p>- een geheel vernieuwde iPOD PDA oplossing voor op het terras</p>\r\n<p>- zowel medewerkers als klanten zijn in staat om bestellingen te maken</p>\r\n<p>- nieuw is de integratie van het kassasysteem met het online eten bestellen via internet</p>'),
(23119, 3798, 76, '<p><strong>online internet ondersteuning</strong></p>\r\n<p>- calamiteiten</p>\r\n<p>- software updates</p>\r\n<p>- instructies</p>\r\n<p>- uitleg</p>\r\n<p>- etc.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>online levering</strong></p>\r\n<p>- de CashCare point of sale software</p>\r\n<p>- installatie van specifieke randapparatuur</p>\r\n<p>- sale software</p>\r\n<p>&nbsp;</p>\r\n<p><strong>20 uur per dag online</strong></p>'),
(23120, 2390, 56, '<p><strong>* gespecialiseerd in afrekensystemen, pinapparatuur en onlinemarketing systemen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* van eenvoudige kassasystemen tot de meest uitgebreide automatiseringsoplossingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* voor horeca, bakkerijen, instellingen, scholen, kledingbranche en retail</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* professionaliteit en persoonlijke benadering</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* m&eacute;t de klant wordt uiteindelijk het doel bepaald</strong></p>'),
(23121, 2390, 3, '<p><strong>- horeca</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- bakkerijen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- instellingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- scholen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- kledingbranche</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- retail</strong></p>'),
