(23204, 3821, 53, '<p><strong>Systemen en software</strong></p>\r\n<p><strong>- POSligne</strong></p>\r\n<p><strong>- POSIOS</strong></p>\r\n<p><strong>- VDS</strong></p>\r\n<p><strong>- HoTouch</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>POSLigne</strong></p>\r\n<p>- van het Franse merk Aures</p>\r\n<p>- modern design en hoge betrouwbaarheid</p>\r\n<p>&nbsp;</p>\r\n<p><strong>POSiOS</strong></p>\r\n<p>- geheel nieuw afrekensysteem</p>\r\n<p>- integratie van TouchPC''s, iPads en data opslag ''in the cloud''</p>\r\n<p>- staat garant voor stabiliteit en flexibiteit</p>\r\n<p>- aansturing van meerdere printers en kassalades</p>\r\n<p>- zeer gebruikersvriendelijk voor zowel de kelner als de manager</p>\r\n<p>- snelle en betrouwbare service</p>\r\n<p>&nbsp;</p>\r\n<p><strong>VDS Afrekensysteem</strong></p>\r\n<p>- talloze nieuwe mogelijkheden in een vertrouwde omgeving</p>\r\n<p>- maakt gebruik van de zeer snelle en betrouwbare Gizmo handterminals</p>\r\n<p>- in de Windows-omgeving</p>\r\n<p>- voor iedereen vertrouwd</p>\r\n<p>- storingsvrij</p>\r\n<p>&nbsp;</p>\r\n<p><strong>HoTouch</strong></p>\r\n<p>- speciaal voor de horeca ontwikkeld</p>\r\n<p>- van kleine tot grote bedrijven</p>\r\n<p>- uitgebreid pakket</p>\r\n<p>- sterk grafisch geori&euml;nteerd</p>\r\n<p>- in zeer korte tijd in te werken</p>\r\n<p>- uit te breiden met mobiele (draadloze) printers en PIN-apparatuur</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(23205, 3821, 86, '<p><strong>WebShop</strong> (met prijsinformatie)</p>'),
(23206, 3821, 76, '<p>- een medewerker richt samen met u het systeem geheel naar wens in</p>\r\n<p>- gedurende een meerdaagse training wordt u vertrouwd gemaakt met het systeem</p>\r\n<p>&nbsp;</p>\r\n<p>- medewerkers zijn 24 uur per dag, 365 dagen per jaar bereikbaar</p>\r\n<p>- verschillende typen van support overeenkomsten</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Support on Demand</strong></p>\r\n<p>- hulp op afstand</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Basis Service Overeenkomst</strong></p>\r\n<p>- &eacute;&eacute;n maal per jaar wordt het systeem gecontroleers en stofvrij gemaakt</p>\r\n<p>- korting op arbeids- en voorrijdtarieven</p>\r\n<p>- beroep op leenapparatuur</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Extra Service Overeenkomst</strong></p>\r\n<p>- met name interessant bij meerdere kassa''s in een netwerk</p>\r\n<p>- het basis-gedeelte</p>\r\n<p>- onderhoud van het netwerk</p>\r\n<p>- installatie van AVG antivirus</p>\r\n<p>- ondersteuning via internet</p>\r\n<p>- altijd de laatste versie beschikbaar</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Full Service Overeenkomst</strong></p>\r\n<p>- alle voordelen van de Extra Overeenkomst</p>\r\n<p>- geen kosten voor voorrijden en arbeid</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(23207, 3036, 56, '<p><strong>* een Unitouch afrekensysteem biedt een totaaloplossing</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* voor horeca, hotel, wellness, bedrijfskantines, recreatieparken en detailhandel</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* al ruim 20 jaar</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* voorzien van alle denkbare functies waar de horeca om vraagt</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* continu&iuml;teit, betrouwbaarheid, eenvoud en snelheid</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* de gehele organisatie kan worden aangestuurd</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met de ''open communicatie-standaard'' </strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* daardoor kunnen belangrijke partners worden gekoppeld aan het Unitouch systeem</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* wij werken met een selectief dealernetwerk</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* uitgekozen op grond van kennis, technische vaardigheden en betrokkenheid</strong></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(23208, 3036, 126, '<p>* <strong>offerte aanvragen</strong> (zie website)</p>'),
(23209, 3039, 56, '<p><strong>* met als specialisatie maatwerk op het gebied van touchscreen kassasystemen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* UPTA streeft ernaar om koploper te zijn als het gaat om innovatie</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* maakt onderdeel uit van unTill Groep Nederland</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* verkoop en support in Zuid West Nederland</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* voor elk segment een passende oplossing</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* aangepast aan de behoefte en het budget van de klant</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* dealer van unTill- en Apostill-kassasystemen</strong></p>'),
