(23231, 5893, 53, '<p><strong>- PolyTouch - kassa-systeem</strong></p>\r\n<p><strong>- PolyMenu - menukaart</strong></p>\r\n<p><strong>- PolyRemote - kassa</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>PolyTouch - kassa-systeem</strong></p>\r\n<p><strong>- </strong>software voor alle horeca-formules</p>\r\n<p>- TAP-koppeling</p>\r\n<p>- achtergrondmuziek</p>\r\n<p>- camerabeveiliging</p>\r\n<p>- handheld kassa</p>\r\n<p>- WWW webordering</p>\r\n<p>- reserveringen</p>\r\n<p>- spaarkaartsysteem</p>\r\n<p>- hotelkey koppeling</p>\r\n<p>- etc.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>PolyMenu - menukaart</strong></p>\r\n<p>- de elektronische tablet menukaart</p>\r\n<p>- volledig in eigen beheer ontwikkeld</p>\r\n<p>- naadloos te koppelen aan uw PolyTouch kassa-systeem</p>\r\n<p>- bestellen doen uw gasten zelf</p>\r\n<p>- op een zeer eenvoudige en intu&iuml;tieve manier</p>\r\n<p>&nbsp;</p>\r\n<p><strong>PolyRemote - kassa</strong></p>\r\n<p>- volledig nieuw waterdicht handheld</p>\r\n<p>- voor gebruik op terras en in restaurant</p>\r\n<p>&nbsp;</p>'),
(23232, 5649, 56, '<p><strong>* het meeste vertrouwde adres voor het produceren van kunststof betaalmunten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* al ruim 30jaar</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* duizenden zeer tevreden klanten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* leverbaar in verschillende modellen en kleuren</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* te voorzien van uw eigen teksten/of logo</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* gemakkelijk te bewaren en te tellen in onze telbakken en telmachines</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* Damen produceert zelf</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* dat geldt ook voor de garderobe labels, roerstaafjes, kunststof doppen etc.</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* snelle levertijden en de laagste prijs</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* in 2002 overgenomen door Tom de Vries</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* sindsdien ook productie van haken, zonweringen en jachten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* machinepark bestaat uit 16 machines</strong></p>'),
(23233, 5649, 97, '<p><strong>vragen over bestellen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>bel 040-2836018</strong></p>'),
(23234, 655, 56, '<p><strong>* uw partner in beveiligings- en veiligheidsplossingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* het fundament van de huidige organisatie ligt in Denemarken en </strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* is in 1901 opgericht</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* de klant staat bij G4S centraal</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met hechte en open relaties</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met onze kennis en expertise kunnen we de best mogelijke oplossingen bieden</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* integriteit is de kern van onze dienstverlening</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* G4S heeft geldtelcentrales in eigen beheer</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* 1 landelijke munttelcentrale en 4 regionale geldtelcentrales</strong></p>\r\n<p>&nbsp;</p>'),
(23235, 655, 53, '<p><strong>- geldtransport</strong></p>\r\n<p><strong>- geldverwerking</strong></p>\r\n<p><strong>- levering van contant geld</strong></p>\r\n<p><strong>- Safe Express (voor het MKB)</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Geldtransport</strong></p>\r\n<p>- een wagenpark van ruim 200 voertuigen</p>\r\n<p>- voorzien van de modernste beveiligings- en communicatiemiddelen</p>\r\n<p>- afvoer van geld</p>\r\n<p>- aanleveren van wisselgeld</p>\r\n<p>- jarenlange expertise</p>\r\n<p>- gepantserd geld- en waardetransport</p>\r\n<p>- beperking van fraude en risico</p>\r\n<p>- landelijke dekking</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Geldverwerking</strong></p>\r\n<p>- G4S verwerkt het cashgeld in eigen beheer</p>\r\n<p>- zorgt ervoor dat het snel op uw rekening staat</p>\r\n<p>- maakt heldere rapportages</p>\r\n<p>- geheel op uw wensen afgestemd</p>\r\n<p>- altijd &eacute;&eacute;n vast aanspreekpunt binnen het geldproces</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Levering van contant geld</strong></p>\r\n<p>- elke dag voldoende wisselgeld in huis (munt- en papiergeld)</p>\r\n<p>- G4S is de grootste producent van papieren muntrollen in Nederland</p>\r\n<p>- in bulk of naar uw specifieke wensen verpakt en geleverd</p>\r\n<p>- ook veilige afvoer van cash geld mogelijk</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Safe Express</strong></p>\r\n<p>- voor het MKB</p>\r\n<p>- veilig, snel en betaalbaar</p>\r\n<p>- het geld wordt opgehaald met een onopvallend waardetransport voertuig</p>\r\n<p>- transporten tot 5.000 euro aan papiergeld</p>\r\n<p>- dit geld wordt gecontroleerd, geteld en snel op uw bankrekening bijgeschreven</p>\r\n<p>- uw regelt uw bankzaken eenvoudig via de goed beveiligde website safe-express.nl</p>\r\n<p>- wisselgeldpakketten kunnen besteld worden</p>\r\n<p>- muntgeld kan meegegeven worden bij het bezoek van de geldtransporteur</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(23236, 2314, 56, '<p><strong>* de grootste merk-onafhankelijke leverancier voor het verwerken van geld</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* in retail, petrol, OV, amusement en de bancaire sector</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met showroom</strong></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>');
