(23441, 1578, 56, '<p><strong>* professionele hygi&euml;ne- en reinigingsoplossingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* toonaangevend bedrijf</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* wereldwijd innovatieve totaaloplossingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* op het gebied van professionele reiniging en hygi&euml;ne</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* inclusief trainingen, logistiek en administratieve ondersteuning</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* klanten in alle marktsegmenten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* wij stellen ons op als partner van de klanten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* 10.500 werknemers wereldwijd</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* actief in meer dan 175 landen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* marktleider in elke regio</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* voortdurend bezig met innovatie</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* duurzaam innoveren zit verweven in de genen van Diversey</strong></p>'),
(23442, 1578, 53, '<p><strong>Het totaalconcept Hygi&euml;ne Zonder Zorgen</strong></p>\r\n<p>- resultaatgericht partnerschap aangaande kwaliteit, effici&euml;ntie en veiligheid</p>\r\n<p>- expertise op het gebied van milieu en wetgeving aangaande reiniging en hygi&euml;ne</p>\r\n<p>- proactieve dienstverlening</p>\r\n<p>- heldere en zichtbare resultaten</p>\r\n<p>- expertise en kennis van uw branche</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Operationele ondersteuning</strong></p>\r\n<p>- het implementeren van systemen en de beheersing van uw hygi&euml;neproces</p>\r\n<p>- praktische instructies</p>\r\n<p>- complete trainings- en opleidingsprogramma''s</p>\r\n<p>- adequate hulp bij storingen</p>\r\n<p>- helpdesk voor al uw vragen</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Continue verbetering</strong></p>\r\n<p>- op basis van intensief onderzoek</p>\r\n<p>- verbetering van systemen en services</p>\r\n<p>- klanten op de hoogte houden van relevante ontwikkelingen</p>\r\n<p>- regelmatige evaluaties en aangeven van verbeterpunten</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Ge&iuml;ntegreerde oplossingen</strong></p>\r\n<p>- wij ontwerpen een hygi&euml;nesysteem dat feilloos aansluit op uw behoeften</p>\r\n<p>- op basis van ons overzichtelijke assortiment met effectieve werkmethoden</p>\r\n<p>- ook hulpmaterialen voor planning en controle van het reinigingsprogramma</p>\r\n<p>- veiligheid, milieu en ergonomie zijn verankerd</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(23443, 1578, 76, '<p><strong>Technical Customer Service</strong></p>\r\n<p>- 7 dagen per week, 24 uur per dag bereikbaar</p>\r\n<p>- ruim 40 uitvoerig opgeleide technici</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Diversey Services Gebouwenonderhoud</strong></p>\r\n<p>- ontwerp en ondersteuning bij gebruik van calculatie- en kwaliteitsmeetsystemen</p>\r\n<p>- juiste keuze van methoden, producten en apparatuur</p>\r\n<p>- demonstraties</p>\r\n<p>- trainingen en cursussen</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Diversey Consulting</strong></p>\r\n<p>- op het gebied van voedselveiligheid en infectiepreventie</p>\r\n<p>&nbsp;</p>'),
(23444, 1578, 54, '<p><strong>- official dealers</strong></p>\r\n<p><strong>- groothandels</strong></p>\r\n<p><strong>- professionele logistieke partners</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Official Dealers:</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Regio Noord-West Nederland</strong></p>\r\n<p><strong>- Hijman Schoonmaakartikelen -</strong> Amsterdam</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Regio Noord en Oost Nederland</strong></p>\r\n<p><strong>- Carel Lurvink -</strong> Enschede</p>\r\n<p><strong>- Neptunus -</strong> Deventer</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Regio Zuid-Nederland</strong></p>\r\n<p><strong>- Schwartzmans Bemu -</strong> Waalwijk</p>\r\n<p><strong>- Castor -</strong> Belfeld</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Regio Zuid-West Nederland</strong></p>\r\n<p><strong>- ASP Cleaning Products -</strong> Zoetermeer</p>\r\n<p><strong>- Haagclean Products -</strong> Rijswijk</p>\r\n<p><strong>- Weska -</strong> Rotterdam</p>'),
(23445, 2420, 56, '<p><strong>* opgericht in 1893</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* inmiddels de vierde generatie aan het roer</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* moderne en servicegerichte groothandel met een zeer breed assortiment</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* schoonmaakartikelen, machines, kantinebenodigdheden, kleding en verpakkingsmateriaal</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* landelijk en internationale klanten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* one-stop shopping is mogelijk</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met topmerken</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* een advies op maat voor iedere klant</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met eigen bezorgdienst en met gerenommeerde postbedrijven en koeriers</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* in staat om binnen 24 uur te leveren</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* servicecenter om machines en producten uit te proberen</strong></p>'),
(23446, 9476, 56, '<p><strong>* in 2012 opgericht door Mischa Frijns</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* een belangrijke en betrouwbare speler op het veelzijdige gebied van bedrijfshygi&euml;ne</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* het juiste gebruik van producten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* het aandragen van alternatieve oplossingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* ASCO is partner van Hagleitner Hygiene International</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* een toonaangevende wereldspeler </strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* op het gebied van innovatieve hygi&euml;ne, green efficiency en vooral service</strong></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
