(23815, 5224, 80, '<p><strong>12 maanden garantie op alle door ons verrichte werkzaamheden en geleverde producten</strong></p>'),
(23816, 5224, 53, '<p><strong>- inbraakwerend</strong></p>\r\n<p><strong>- brandwerend</strong></p>\r\n<p><strong>- inbouwkluizen</strong></p>\r\n<p><strong>- sleutelkasten</strong></p>\r\n<p><strong>- afstortkasten</strong></p>\r\n<p><strong>- buispost</strong></p>\r\n<p><strong>- waarden-indicaties</strong></p>\r\n<p><strong>- diversen</strong></p>\r\n<p><strong>- opties</strong></p>\r\n<p><strong>- occasions</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Inbraakwerend</strong></p>\r\n<p>- star-serie</p>\r\n<p>- europa-serie</p>\r\n<p>- hdv-serie</p>\r\n<p>- s-serie</p>\r\n<p>- eurocity</p>\r\n<p>- bk se-serie</p>\r\n<p>- star veiligheidskasten</p>\r\n<p>- veiligheidsladenkasten</p>\r\n<p>- waardekamers</p>\r\n<p>- bk modular vault room</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Brandwerend</strong></p>\r\n<p>- eurocity-duo-serie</p>\r\n<p>- datasafes</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Inbouwkluizen</strong></p>\r\n<p>- bk-vloerkluzien</p>\r\n<p>- bk-muurkluizen</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Sleutelkasten</strong></p>\r\n<p>- star s2 sleutelkasten</p>\r\n<p>- star n/o sleutelkasten</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Afstortkasten</strong></p>\r\n<p>- cashboxen</p>\r\n<p>- star-afstortkasten</p>\r\n<p>- bk-afstortkasten</p>\r\n<p>- bk kluis in kluis</p>\r\n<p>- eurocity-afstortkast</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Buispost</strong></p>\r\n<p>- euro-air</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Waarden-indicaties</strong></p>\r\n<p>- waarden-indicatielijst</p>\r\n<p>- euronormering</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Diversen</strong></p>\r\n<p>- geldtransportluik</p>\r\n<p>- wapenkasten</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Opties</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>Occasions</strong></p>'),
