(23821, 764, 3, '<p><strong>- beveligingsbedrijven</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- gemeenten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- politie</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- horecaondernemingen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- universiteiten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- retailers</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- etc.</strong></p>'),
(23822, 764, 53, '<p><strong>- priv&eacute;safes</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- brand-en/of inbraakwerende eurodsafes</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- archief- en waardekasten</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- brandwerende safes</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- datasafes</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- computer- en laptopbeveiliging</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- winkel- en afstortkluizen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- muur- en vloerkluizen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- hotelsafes</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- sleutelberging</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- wapenkluizen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>- veiligheidsproducten</strong></p>'),
