(23826, 2753, 56, '<p><strong>* al meer dan 30 jaar gespecialiseerd importeur en leverancier</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* hoogwaardige toegangscontrolesystemen en componenten voor deurbeveiliging</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* met name elektrische sloten, hotelkaartsloten, hotelkluizen, codesloten etc.</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* vertegenwoordigt en levert merken van wereldklasse</strong></p>'),
(23827, 2753, 75, '<p><strong>productspecialisten voor alle mogelijke adviezen</strong></p>'),
(23828, 2753, 55, '<p>- <strong>Ingersoll Rand</strong> - deurdrangers en paniekopeners van wereldklasse</p>\r\n<p>&nbsp;</p>\r\n<p>- <strong>Cylock</strong> - elektronische sleutelen cilindersystemen</p>\r\n<p>&nbsp;</p>\r\n<p>- <strong>Onity</strong> - code-kaartsloten (o.a. voor hotels, zorgsectoren bedrijven)</p>\r\n<p>&nbsp;</p>\r\n<p>- <strong>Digital</strong> - codesloten</p>\r\n<p>&nbsp;</p>\r\n<p>- <strong>Essex</strong> - codesloten</p>\r\n<p>&nbsp;</p>\r\n<p>-<strong> Rembrandt RFID</strong> - kaartsloten voor hotels</p>'),
(23829, 1623, 56, '<p><strong>een makkelijk te bedienen draadloos portiersbeveiligingssysteem</strong></p>'),
(23830, 8715, 56, '<p><strong>* sinds 1897</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* sinds 2001 worden alle werkzaamheden uitgevoerd vanaf de Protonstraat in Groningen</strong></p>'),
(23831, 4028, 56, '<p><strong>* draagt zorg voor veiligheid</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* in bedrijven, hotels, horeca, bouwobjecten, winkels en evenementen</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* verricht onderzoek (o.a. diefstal en fraudes)</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* sinds 2000</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* bij meer dan 450 bedrijven</strong></p>'),
(23832, 768, 56, '<p><strong>* in 1996 opgericht door Thijs Klifman</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* full-service aanbieder </strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* winkeldiefstalbeveiliging, inbraakbeveiliging, camerasystemen en toegangscontrole</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* sinds 2009 officieel erkend Installatiebedrijf</strong></p>\r\n<p>&nbsp;</p>\r\n<p><strong>* eigen technische dienst</strong></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>'),
(23833, 768, 75, '<p><strong>vrijblijvende security-analyse door &eacute;&eacute;n van onze gecertificeerde adviseurs</strong></p>'),
(23834, 768, 119, '<p><strong>promotievideo X-Tronx Security Systems</strong> (zie website)</p>'),
(23835, 9618, 0, ''),
(23836, 3435, 97, '<p>Download <a href="http://www.dickschaap.nl/wp-content/uploads/bestelformulier_DickSchaap.pdf" target="_blank">&lt;hier&gt;</a> een beknopte bestellijst</p>'),
(23837, 3435, 56, '<h4>Kwaliteit<br /><br /></h4>\r\n<ul>\r\n<li>hoogwaardige producten</li>\r\n<li>groot netwerk van lokale tuinders</li>\r\n<li>groot assortiment biologische producten</li>\r\n<li>ieder seizoen verse seizoensproducten</li>\r\n</ul>\r\n<h4><br />Servive<br /><br /></h4>\r\n<ul>\r\n<li>betrouwbaar</li>\r\n<li>voor klanten altijd bereikbaar</li>\r\n<li>flexibel</li>\r\n</ul>\r\n<h4><br />Exclusief<br /><br /></h4>\r\n<ul>\r\n<li>altijd op zoek om exclusieve producten te kunnen leveren</li>\r\n</ul>'),
(23838, 3435, 53, '<h4>Maatwerk<br /><br /></h4>\r\n<ul>\r\n<li>vers gesneden groenten en fruit</li>\r\n<li>principe alles leverbaar op dit gebied.</li>\r\n<li>groot assortiment biologische producten</li>\r\n</ul>\r\n<h4><br />Totaal pakketten<br /><br /></h4>\r\n<ul>\r\n<li>aardappelen, groente en fruit</li>\r\n<li>verse panklare groenten</li>\r\n<li>brood van de warme bakker</li>\r\n<li>tegen een kleine meerprijs u ook alle overige producten leverbaar</li>\r\n</ul>'),
(23839, 3435, 30, '<h4>Duurzaam ondernemen<br /><br /></h4>\r\n<ul>\r\n<li>bedrijfsvoering gericht op duurzaamheid</li>\r\n<li>altijd leerplekken en werkplekken voor Wajong jongeren beschikbaar</li>\r\n<li>gekoeld vervoer, mede dankzij koelmotoren van Carrosseriefabriek Harderwijk</li>\r\n<li>bestelauto&rsquo;s nooit ouder dan 4 jaar</li>\r\n<li>nieuwste bestelauto voorzien van zonnepanelen</li>\r\n<li>prefereren CO2 neutralere producten</li>\r\n</ul>'),
(23840, 3435, 450, '<ul>\r\n<li>24/7 bereikbaar</li>\r\n<li>eigen logistiek systeem ontwikkeld</li>\r\n<li>snel inspelen op wensen rondom levertijden en verpakkingen</li>\r\n</ul>'),
